"""Run the positive control and three required rejection controls through the gate."""
import datetime
import json
from pathlib import Path
import sys
from compare import run

ROOT = Path(__file__).resolve().parent
results = {}
for name, expected in [('pass', 'passed'), ('mismatch', 'failed'), ('axiom', 'failed'), ('definition', 'failed')]:
    result = run(ROOT / 'controls' / (name + '.json'))
    log = Path(result['log']).read_text()
    if name == 'mismatch':
        reason = 'does not match' in log or 'Mismatch' in log
    elif name == 'axiom':
        reason = 'untrusted' in log
    elif name == 'definition':
        reason = 'target' in log and result['steps'][-1]['name'].startswith('Compare')
    else:
        reason = result['kernel_accepts'] and result['comparator_accepts']
    results[name] = {'expected': expected, 'observed': result['status'], 'expected_reason_observed': reason,
                     'kernel_accepts': result['kernel_accepts'], 'comparator_accepts': result['comparator_accepts']}
status = 'passed' if all(x['expected'] == x['observed'] and x['expected_reason_observed'] for x in results.values()) else 'failed'
summary = {'status': status, 'validated_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'controls': results}
(ROOT / 'controls' / 'SUMMARY.json').write_text(json.dumps(summary, indent=2) + '\n')
print(json.dumps(summary), flush=True)
sys.exit(0 if status == 'passed' else 1)
